                           char *key, size_t key_max,
                           char *value, size_t value_max)
{
    uint8_t *opt_val = NULL;
    int opt_len;
    uint8_t **opt_pos = (uint8_t **)pos;

    opt_val = coap_iterate_option(pkt, COAP_OPT_URI_QUERY, opt_pos, &opt_len);

    if (opt_val == NULL) {
        return 0; /* no more options */
    }

    /* Found a URI-Query option, now parse it. */
    const char *separator = memchr(opt_val, '=', opt_len);
    size_t key_len;
    size_t val_len = 0;

