        key_len = separator - (char *)opt_val;
        val_len = opt_len - key_len - 1;
    }
    else {
        key_len = opt_len;
    }

    if (key_len >= key_max) {
        return -ENOSPC;
    }
    memcpy(key, opt_val, key_len);
    key[key_len] = '\\0';

